-- Issue #71 (Aurelle claimants + Rising): private Tier-1 pledges and Rising records. Additive tables only.
CREATE TABLE IF NOT EXISTS aurelle_pledges ( clerk_user_id TEXT COLLATE "C" PRIMARY KEY REFERENCES citizens(clerk_user_id) ON DELETE CASCADE, claimant_id TEXT COLLATE "C" NOT NULL CHECK(claimant_id IN ('vaelcourt','brightvane','larkspire')), request_id TEXT COLLATE "C" NOT NULL UNIQUE, pledged_at BIGINT NOT NULL, policy TEXT COLLATE "C" NOT NULL CHECK(policy = 'tier1-human-v1') );
CREATE TABLE IF NOT EXISTS aurelle_risings ( id TEXT COLLATE "C" PRIMARY KEY, claimant_id TEXT COLLATE "C" NOT NULL CHECK(claimant_id IN ('vaelcourt','brightvane','larkspire')), opened_at BIGINT NOT NULL, closes_at BIGINT NOT NULL CHECK(closes_at > opened_at), pledges_at_open BIGINT NOT NULL CHECK(pledges_at_open >= 1), weekly_humans_at_open BIGINT NOT NULL CHECK(weekly_humans_at_open >= 1), unrest_at_open BIGINT NOT NULL, resolved_at BIGINT, outcome TEXT COLLATE "C" CHECK(outcome IS NULL OR outcome IN ('succeeded','failed')), pledges_at_close BIGINT, weekly_humans_at_close BIGINT, stability_at_close BIGINT, CHECK((resolved_at IS NULL) = (outcome IS NULL)) );
CREATE INDEX IF NOT EXISTS idx_aurelle_pledges_claimant ON aurelle_pledges(claimant_id);
CREATE INDEX IF NOT EXISTS idx_aurelle_risings_opened ON aurelle_risings(opened_at);
